"""Seven-page customer report with native Word equations and measured history."""
from pathlib import Path
import runpy
from docx.oxml import OxmlElement
from docx.oxml.ns import qn
from docx.shared import Pt, Mm

ROOT=Path(__file__).resolve().parents[1]
ns=runpy.run_path(str(ROOT/'scripts/build_client_document.py'))
doc=ns['doc'];p=ns['p'];h=ns['h'];table=ns['table'];code=ns['code'];link=ns['link']
for node in list(doc._element.body):
    if node.tag!=qn('w:sectPr'):doc._element.body.remove(node)
doc.styles['Normal'].paragraph_format.space_after=Pt(4)
doc.styles['Normal'].paragraph_format.line_spacing=1.02
eq_number=0


def run(value):
    node=OxmlElement('m:r');text=OxmlElement('m:t');text.text=str(value);text.set(qn('xml:space'),'preserve');node.append(text);return node


def append(parent,items):
    for item in items if isinstance(items,(list,tuple)) else [items]:
        parent.append(run(item) if isinstance(item,(str,int,float)) else item)


def sub(base,index):
    node=OxmlElement('m:sSub');e=OxmlElement('m:e');append(e,base);s=OxmlElement('m:sub');append(s,index);node.extend([e,s]);return node


def sup(base,index):
    node=OxmlElement('m:sSup');e=OxmlElement('m:e');append(e,base);s=OxmlElement('m:sup');append(s,index);node.extend([e,s]);return node


def frac(top,bottom):
    node=OxmlElement('m:f');a=OxmlElement('m:num');append(a,top);b=OxmlElement('m:den');append(b,bottom);node.extend([a,b]);return node


def sqrt(value):
    node=OxmlElement('m:rad');pr=OxmlElement('m:radPr');hide=OxmlElement('m:degHide');hide.set(qn('m:val'),'1');pr.append(hide)
    degree=OxmlElement('m:deg');e=OxmlElement('m:e');append(e,value);node.extend([pr,degree,e]);return node


def eq(*items):
    global eq_number
    eq_number+=1
    row=doc.add_paragraph();row.alignment=1;row.paragraph_format.space_before=Pt(2);row.paragraph_format.space_after=Pt(5)
    om=OxmlElement('m:oMath');append(om,list(items)+['   ('+str(eq_number)+')']);row._p.append(om)


def page(title):
    row=doc.add_heading(title,1)
    row.paragraph_format.page_break_before=True


doc.add_paragraph('AirAntiCollision','Title')
p('Алгоритм, результаты исследования и работа системы',bold=True,size=13)
p('Техническое описание для передачи заказчику  •  24 октября 2026',size=9)
