page('Математика раннего признака сближения')
p('Используются только свежие измерения детектора, а не предсказанные размеры трекера. Окно истории T - до 0,6 с; до первого вывода нужны T ≥ 0,3 с, не менее пяти измерений и медианный размер s̃ ≥ 6 пикселей. Для робастного наклона оставляется не более 32 равномерно выбранных измерений.')
eq('a(y) = ',sub('median','j>i'),frac([sub('y','j'),' − ',sub('y','i')],[sub('t','j'),' − ',sub('t','i')]),',   β(y) = ',sub('median','i'),'(',sub('y','i'),' − a(y)',sub('t','i'),')')
eq('g = a(ln s),   ',sub('v','x'),' = a(u),   ',sub('v','y'),' = a(v),   δ = ',frac(sqrt([sup(sub('v','x'),'2'),' + ',sup(sub('v','y'),'2')]),'s̃'))
